CREATE OR REPLACE FUNCTION nexus.gc_expire_quarantine( dim int, p_tenant_id text, p_quarantine_collection text, p_origin_collection text, p_cutoff text, p_floor_fraction float8, p_floor_min_chunks int, p_force boolean ) RETURNS TABLE(expired bigint, refused bigint) LANGUAGE plpgsql SECURITY INVOKER AS $$ DECLARE v_mine bigint; v_chashes bytea[]; v_protected bytea[]; v_expired bigint; v_refused bigint; v_frac float8; BEGIN IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'gc_expire_quarantine: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
SELECT count(*), array_agg(c.chash) FILTER ( WHERE COALESCE(c.metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = p_origin_collection AND m.chash = c.chash )), array_agg(c.chash) FILTER ( WHERE COALESCE(c.metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = p_origin_collection AND m.chash = c.chash )) INTO v_mine, v_chashes, v_protected FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection -- Skip the rows tagged quarantined_by = 'engine-reaper' (nexus.reaper_owns_quarantined_row, vectors-024-2): -- the engine's own rows are expired by nexus.reaper_expire_quarantine, never here. This comment keeps the -- literal in the function's stored body (prosrc) as a TRANSITION SHIM for conexus's existing deploy census, -- which matches on it; the census should read pg_proc for nexus.reaper_owns_quarantined_row instead, and the -- comment can go once it does. It is not the contract: the contract is the call below. AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE;
v_expired := COALESCE(array_length(v_chashes, 1), 0); v_refused := COALESCE(array_length(v_protected, 1), 0);
IF v_expired = 0 THEN RETURN QUERY SELECT 0::bigint, v_refused; RETURN; END IF;
v_frac := v_expired::float8 / v_mine::float8; IF v_expired >= p_floor_min_chunks AND v_frac > p_floor_fraction AND NOT p_force THEN RETURN QUERY SELECT 0::bigint, v_expired + v_refused; RETURN; END IF;
-- The ownership exclusion is repeated here: a row the reaper re-moved (a fresh tag) between the read above -- and this delete is the engine's now, and is not taken. -- What is reported and audited is what this DELETE really removed (RETURNING), not what the read above chose: -- a row the reaper re-moved in between is not counted. WITH del AS ( DELETE FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND c.chash = ANY(v_chashes) AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE RETURNING c.chash ) SELECT COALESCE(array_agg(d.chash ORDER BY d.chash), '{}'::bytea[]) INTO v_chashes FROM del d; v_expired := COALESCE(array_length(v_chashes, 1), 0);
-- nexus-sybbh: the audit row in the SAME transaction as the delete (catalog-033-3); truncated at 5000 chashes. IF v_expired > 0 THEN INSERT INTO nexus.gc_audit (tenant_id, operation, collection, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'gc_expire_quarantine', p_quarantine_collection, 'engine', false, v_expired, COALESCE( (SELECT jsonb_agg(encode(x, 'hex')) FROM unnest(v_chashes[1:LEAST(v_expired, 5000)]) x), '[]'::jsonb), jsonb_build_object('origin_collection', p_origin_collection, 'refused', v_refused, 'cutoff', p_cutoff) || CASE WHEN v_expired > 5000 THEN jsonb_build_object('chashes_truncated', true, 'chashes_stored', 5000) ELSE '{}'::jsonb END ); END IF;
RETURN QUERY SELECT v_expired, v_refused; END; $$

rollback.sql:
CREATE OR REPLACE FUNCTION nexus.gc_expire_quarantine(
    dim                      int,
    p_tenant_id              text,
    p_quarantine_collection  text,
    p_origin_collection      text,
    p_cutoff                 text,
    p_floor_fraction         float8,
    p_floor_min_chunks       int,
    p_force                  boolean
)
RETURNS TABLE(expired bigint, refused bigint)
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
    v_mine      bigint;
    v_chashes   bytea[];
    v_protected bytea[];
    v_expired   bigint;
    v_refused   bigint;
    v_frac      float8;
BEGIN
    IF dim NOT IN (384, 768, 1024) THEN
        RAISE EXCEPTION
            'gc_expire_quarantine: unsupported dim %. Supported values: 384, 768, 1024',
            dim;
    END IF;

    SELECT count(*),
           array_agg(c.chash) FILTER (
               WHERE COALESCE(c.metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff
                 AND NOT EXISTS (
                       SELECT 1 FROM nexus.catalog_document_chunks m
                        WHERE m.tenant_id  = c.tenant_id
                          AND m.collection = p_origin_collection
                          AND m.chash      = c.chash
                     )),
           array_agg(c.chash) FILTER (
               WHERE COALESCE(c.metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff
                 AND EXISTS (
                       SELECT 1 FROM nexus.catalog_document_chunks m
                        WHERE m.tenant_id  = c.tenant_id
                          AND m.collection = p_origin_collection
                          AND m.chash      = c.chash
                     ))
      INTO v_mine, v_chashes, v_protected
      FROM nexus.chunks c
     WHERE c.tenant_id  = p_tenant_id
       AND c.collection = p_quarantine_collection
       AND COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection;

    v_expired := COALESCE(array_length(v_chashes, 1), 0);
    v_refused := COALESCE(array_length(v_protected, 1), 0);

    IF v_expired = 0 THEN
        RETURN QUERY SELECT 0::bigint, v_refused;
        RETURN;
    END IF;

    v_frac := v_expired::float8 / v_mine::float8;
    IF v_expired >= p_floor_min_chunks AND v_frac > p_floor_fraction AND NOT p_force THEN
        RETURN QUERY SELECT 0::bigint, v_expired + v_refused;
        RETURN;
    END IF;

    DELETE FROM nexus.chunks c
     WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection
       AND c.chash = ANY(v_chashes);

    INSERT INTO nexus.gc_audit
        (tenant_id, operation, collection, actor, dry_run, chash_count, chashes, details)
    VALUES (
        p_tenant_id, 'gc_expire_quarantine', p_quarantine_collection, 'engine', false, v_expired,
        COALESCE(
            (SELECT jsonb_agg(encode(x, 'hex'))
               FROM unnest(v_chashes[1:LEAST(COALESCE(array_length(v_chashes, 1), 0), 5000)]) x),
            '[]'::jsonb),
        jsonb_build_object('origin_collection', p_origin_collection, 'refused', v_refused, 'cutoff', p_cutoff)
            || CASE WHEN COALESCE(array_length(v_chashes, 1), 0) > 5000
                    THEN jsonb_build_object('chashes_truncated', true, 'chashes_stored', 5000)
                    ELSE '{}'::jsonb END
    );

    RETURN QUERY SELECT v_expired, v_refused;
END;
$$
